1	import type { Metadata } from "next";
2	import Link from "next/link";
3	import { notFound } from "next/navigation";
4	import { db } from "@/lib/db";
5	import { currentUser } from "@/lib/auth";
6	import { Section } from "@/components/marketing/primitives";
7	import { ModCard } from "@/components/mods/ModCard";
8	import { AddToServerWidget } from "@/components/mods/AddToServerWidget";
9	import { AuthorBadge } from "@/components/mods/AuthorBadge";
10	import { GalleryStrip } from "@/components/mods/GalleryStrip";
11	import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
12	import { APP_URL } from "@/components/marketing/StructuredData";
13	import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";
14	import { renderMarkdown } from "@/lib/blog";
15	import {
16	  getCatalogMod,
17	  listCatalogSlugs,
18	  relatedCatalogMods,
19	  recommendedPlanFor,
20	  resolveDownloadUrl,
21	  listModComments,
22	  getMyModRating,
23	  formatDownloads,
24	  formatBytes,
25	  SOURCE_LABEL,
26	} from "@/lib/mods-catalog";
27	
28	export const dynamic = "force-dynamic";
29	
30	type Params = { params: Promise<{ family: string; slug: string }> };
31	
32	export async function generateStaticParams(): Promise<Array<{ family: string; slug: string }>> {
33	  return listCatalogSlugs();
34	}
35	
36	export async function generateMetadata({ params }: Params): Promise<Metadata> {
37	  const { family, slug } = await params;
38	  const mod = await getCatalogMod(family, slug);
39	  if (!mod) return { title: "Mod not found" };
40	  const title = `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`;
41	  const description =
42	    mod.description ||
43	    `${mod.name} for ${mod.gameFamilyLabel}, verified against ${SOURCE_LABEL[mod.source] ?? mod.source} — real download counts, supported versions, and a direct download link.`;
44	  return {
45	    title,
46	    description,
47	    alternates: { canonical: `/mods/${mod.gameFamily}/${mod.slug}` },
48	    openGraph: {
49	      title,
50	      description,
51	      type: "website",
52	      url: `${APP_URL}/mods/${mod.gameFamily}/${mod.slug}`,
53	      ...(mod.iconUrl ? { images: [mod.iconUrl] } : {}),
54	    },
55	  };
56	}
57	
58	export default async function ModDetailPage({ params }: Params) {
59	  const { family, slug } = await params;
60	  const mod = await getCatalogMod(family, slug);
61	  if (!mod) notFound();
62	
63	  const user = await currentUser();
64	  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
65	    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
66	    relatedCatalogMods(mod, 4),
67	    resolveDownloadUrl(mod),
68	    listModComments(mod.id, { take: 10 }),
69	    user ? getMyModRating(mod.id, user.id) : Promise.resolve(null),
70	  ]);
71	  const recommended = recommendedPlanFor(mod, gamePlans);
72	  const downloads = formatDownloads(mod.downloads);
73	  const fileSize = formatBytes(mod.fileBytes);
74	  // A mod's OWN screenshot/icon is the best backdrop when it has one (real
75	  // gallery art, blurred+dimmed so it reads as ambience, not a competing
76	  // image). Most catalogue entries don't carry either — confirmed live
77	  // 2026-09-20: every github-sourced mod (CounterStrikeSharp included) has
78	  // iconUrl: null and galleryUrls: [] — which is exactly why this page's
79	  // hero used to render nothing at all for them. Falling back to the same
80	  // per-game hero art the family browse page already uses
81	  // (GAME_ART_SLUG[family].hero) means a detail page is never blank; shown
82	  // less blurred/more opaque than an own-screenshot backdrop since it's
83	  // meant to read as "this is a real game", not just ambient texture.
84	  const familyHeroSlug = GAME_ART_SLUG[mod.gameFamily as GameFamily]?.hero;
85	  const ownHeroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;
86	  const heroImage = ownHeroImage ?? (familyHeroSlug ? `/games/art/${familyHeroSlug}_hero.jpg` : null);
87	  const heroIsGameArt = !ownHeroImage && !!heroImage;
88	  // Real longer body from the source's own project page (Modrinth's `body`,
89	  // see scripts/backfill-modrinth-descriptions.ts) — null until backfilled,
90	  // or for sources with nothing longer to offer. Capped at 6000 chars before
91	  // rendering: a small guard against a handful of extreme-length project
92	  // pages, not a real-world limit for the vast majority of bodies.
93	  const longDescriptionHtml = mod.longDescription ? renderMarkdown(mod.longDescription.slice(0, 6000)) : null;
94	
95	  return (
96	    <>
97	      {/* SoftwareApplication, not Product — this is a free, third-party-hosted
98	          download, not something Nxeon sells. price: "0" is the accurate,
99	          Google-documented way to mark a free application. aggregateRating is
100	          now real (ModRating), so it's included ONLY when at least one exists
101	          — never a fabricated 0/0. */}
102	      <script
103	        type="application/ld+json"
104	        // eslint-disable-next-line react/no-danger
105	        dangerouslySetInnerHTML={{
106	          __html: JSON.stringify({
107	            "@context": "https://schema.org",
108	            "@type": "SoftwareApplication",
109	            name: mod.name,
110	            applicationCategory: "GameApplication",
111	            operatingSystem: mod.gameFamilyLabel,
112	            description: mod.description || `${mod.name} for ${mod.gameFamilyLabel}.`,
113	            ...(mod.iconUrl ? { image: mod.iconUrl } : {}),
114	            ...(download ? { downloadUrl: download.url } : {}),
115	            offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
116	            ...(mod.avgRating != null
117	              ? {
118	                  aggregateRating: {
119	                    "@type": "AggregateRating",
120	                    ratingValue: mod.avgRating.toFixed(1),
121	                    reviewCount: mod.ratingCount,
122	                  },
123	                }
124	              : {}),
125	          }),
126	        }}
127	      />
128	
129	      <section className="relative overflow-hidden">
130	        {heroImage && (
131	          <div className="absolute inset-0 -z-10">
132	            {/* eslint-disable-next-line @next/next/no-img-element */}
133	            <img
134	              src={heroImage}
135	              alt=""
136	              className={`h-full w-full object-cover ${heroIsGameArt ? "opacity-30" : "opacity-25 blur-sm"}`}
137	            />
138	            {/* var(--color-bg), not var(--bg) — the latter is never defined in
139	                globals.css (only --color-bg is), so this gradient stop used to
140	                be silently invalid CSS and render nothing at all. The
141	                per-family browse page's identical gradient
142	                (app/(marketing)/mods/games/[family]/page.tsx) has the same
143	                latent bug; flagged as a follow-up rather than touched here. */}
144	            <div className="absolute inset-0 bg-gradient-to-t from-[var(--color-bg)] via-[var(--color-bg)]/80 to-[var(--color-bg)]/40" />
145	          </div>
146	        )}
147	        <div className="rail py-16 sm:py-20">
148	          <p className="text-xs font-semibold uppercase tracking-widest text-brand-300">
149	            <Link href="/mods" className="hover:underline">
150	              NxLabs
151	            </Link>{" "}
152	            /{" "}
153	            <Link href={`/mods/games/${mod.gameFamily}`} className="hover:underline">
154	              {mod.gameFamilyLabel}
155	            </Link>
156	          </p>
157	          <div className="mt-3 flex flex-wrap items-center gap-4">
158	            {mod.iconUrl ? (
159	              // eslint-disable-next-line @next/next/no-img-element
160	              <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
161	            ) : (
162	              <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.04] text-2xl font-bold text-[var(--fg-muted)]">
163	                {mod.name.slice(0, 1)}
164	              </div>
165	            )}
166	            <div>
167	              <h1 className="text-3xl font-bold text-[var(--fg)] sm:text-4xl">{mod.name}</h1>
168	              {mod.authorName && (
169	                <div className="mt-1">
170	                  <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />
171	                </div>
172	              )}
173	            </div>
174	          </div>
175	          {mod.description && <p className="mt-4 max-w-2xl text-[var(--fg-muted)]">{mod.description}</p>}
176	        </div>
177	      </section>
178	
179	      <Section>
180	        <div className="mx-auto grid max-w-5xl gap-8 lg:grid-cols-[1.4fr_1fr]">
181	          <div className="space-y-6">
182	            {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}
183	
184	            {longDescriptionHtml && (
185	              <div className="card p-6">
186	                <h2 className="text-lg font-semibold text-[var(--fg)]">Description</h2>
187	                {/* Real body from the source's own project page (Modrinth's
188	                    `body`), rendered through the same sanitizing markdown
189	                    renderer the blog uses (escapes text before any tag is
190	                    produced) — never raw third-party HTML. Distinct from the
191	                    short tagline already shown in the header above. */}
192	                <div
193	                  className="mt-3 text-sm text-[var(--fg-muted)]"
194	                  // eslint-disable-next-line react/no-danger
195	                  dangerouslySetInnerHTML={{ __html: longDescriptionHtml }}
196	                />
197	              </div>
198	            )}
199	
200	            <div className="card p-6">
201	              <h2 className="text-lg font-semibold text-[var(--fg)]">Download</h2>
202	              {download ? (
203	                <>
204	                  <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
205	                    {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
206	                  </a>
207	                </>
208	              ) : (
209	                <p className="mt-3 text-sm text-[var(--fg-muted)]">No download link is available for this entry right now.</p>
210	              )}
211	
212	              <div className="mt-6">
213	                <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
214	              </div>
215	
216	              {!mod.upstreamOk && (
217	                <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
218	                  {mod.upstreamNote || "This mod is no longer supported by its source."}
219	                </p>
220	              )}
221	            </div>
222	
223	            <RatingsAndComments
224	              modId={mod.id}
225	              avgRating={mod.avgRating}
226	              ratingCount={mod.ratingCount}
227	              initialComments={commentsPage.comments}
228	              initialCursor={commentsPage.nextCursor}
229	              myRating={myRating}
230	              isLoggedIn={!!user}
231	              isAdmin={user?.role === "ADMIN"}
232	              loginHref={`/login?next=${encodeURIComponent(`/mods/${mod.gameFamily}/${mod.slug}`)}`}
233	            />
234	          </div>
235	
236	          <aside className="space-y-6">
237	            <div className="card p-6">
238	              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Details</h2>
239	              <dl className="mt-4 space-y-3 text-sm">
240	                <Row label="Game">{mod.gameFamilyLabel}</Row>
241	                <Row label="Category">{mod.category}</Row>
242	                <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
243	                {mod.license && <Row label="License">{mod.license}</Row>}
244	                {downloads && <Row label="Downloads">{downloads}</Row>}
245	                {fileSize && <Row label="File size">{fileSize}</Row>}
246	                {mod.gameVersions.length > 0 && (
247	                  <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>
248	                )}
249	                {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
250	                {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
251	                {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
252	                <Row label="Verified">
253	                  {mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}
254	                </Row>
255	              </dl>
256	            </div>
257	
258	            <div className="card p-6">
259	              <h2 className="text-sm font-semibold uppercase tracking-wide text-[var(--fg-muted)]">Recommended server</h2>
260	              {recommended ? (
261	                <p className="mt-3 text-sm text-[var(--fg-muted)]">
262	                  Works well on <span className="text-[var(--fg)]">{recommended.planName}</span> (
263	                  {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM) or higher —{" "}
264	                  <Link href={`/${mod.gameFamily}-server-hosting`} className="text-brand-300 underline underline-offset-2">
265	                    see plans
266	                  </Link>
267	                  .
268	                </p>
269	              ) : (
270	                <p className="mt-3 text-sm text-[var(--fg-muted)]">
271	                  {mod.impactNote || "This is a light install and should run fine on any active plan for this game."}
272	                </p>
273	              )}
274	            </div>
275	          </aside>
276	        </div>
277	
278	        {related.length > 0 && (
279	          <div className="mx-auto mt-16 max-w-5xl">
280	            <h2 className="text-lg font-semibold text-[var(--fg)]">More for {mod.gameFamilyLabel}</h2>
281	            <div className="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
282	              {related.map((r) => (
283	                <ModCard key={r.id} mod={r} href={`/mods/${r.gameFamily}/${r.slug}`} />
284	              ))}
285	            </div>
286	          </div>
287	        )}
288	      </Section>
289	    </>
290	  );
291	}
292	
293	function Row({ label, children }: { label: string; children: React.ReactNode }) {
294	  return (
295	    <div className="flex items-start justify-between gap-4">
296	      <dt className="text-[var(--fg-muted)]">{label}</dt>
297	      <dd className="text-right text-[var(--fg)]">{children}</dd>
298	    </div>
299	  );
300	}
