1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { requireUser } from "@/lib/auth";
4	import { db } from "@/lib/db";
5	import { PageShell } from "@/components/nx/PageShell";
6	import { ModCard } from "@/components/mods/ModCard";
7	import { AddToServerWidget } from "@/components/mods/AddToServerWidget";
8	import { AuthorBadge } from "@/components/mods/AuthorBadge";
9	import { GalleryStrip } from "@/components/mods/GalleryStrip";
10	import { RatingsAndComments } from "@/components/mods/RatingsAndComments";
11	import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";
12	import { renderMarkdown } from "@/lib/blog";
13	import {
14	  getCatalogMod,
15	  relatedCatalogMods,
16	  recommendedPlanFor,
17	  resolveDownloadUrl,
18	  listModComments,
19	  getMyModRating,
20	  formatDownloads,
21	  formatBytes,
22	  SOURCE_LABEL,
23	} from "@/lib/mods-catalog";
24	
25	export const dynamic = "force-dynamic";
26	
27	/**
28	 * Portal's own mod-detail route — genuinely separate from the public
29	 * /mods/[family]/[slug] page (item 1 of the NxLabs brief). Same underlying
30	 * data (lib/mods-catalog.ts), rendered through the Nexion portal shell by
31	 * virtue of living under app/dashboard/**, with its own breadcrumbs back
32	 * into /dashboard/nxlabs instead of the public catalog.
33	 */
34	export default async function PortalModDetailPage({ params }: { params: Promise<{ family: string; slug: string }> }) {
35	  const { family, slug } = await params;
36	  const user = await requireUser();
37	  const mod = await getCatalogMod(family, slug);
38	  if (!mod) notFound();
39	
40	  const [gamePlans, related, download, commentsPage, myRating] = await Promise.all([
41	    db.gamePlan.findMany({ where: { gameFamily: mod.gameFamily, active: true }, orderBy: { priceCents: "asc" } }),
42	    relatedCatalogMods(mod, 4),
43	    resolveDownloadUrl(mod),
44	    listModComments(mod.id, { take: 10 }),
45	    getMyModRating(mod.id, user.id),
46	  ]);
47	  const recommended = recommendedPlanFor(mod, gamePlans);
48	  const downloads = formatDownloads(mod.downloads);
49	  const fileSize = formatBytes(mod.fileBytes);
50	  // Same fallback the public detail page uses (item 2 of the NxLabs brief):
51	  // most catalogue rows (every github-sourced mod included) have neither a
52	  // gallery screenshot nor an icon, and this page used to render nothing
53	  // visual at all for them. Falls back to the family's own hero art
54	  // (GAME_ART_SLUG, same source the per-family browse page already uses) so
55	  // the header always has real game context, contained inside a normal
56	  // rounded panel here rather than the marketing page's full-bleed section —
57	  // the dashboard shell has a fixed content width against the sidebar, no
58	  // room for a viewport-edge bleed.
59	  const familyHeroSlug = GAME_ART_SLUG[mod.gameFamily as GameFamily]?.hero;
60	  const ownHeroImage = mod.galleryUrls[0] ?? mod.iconUrl ?? null;
61	  const heroImage = ownHeroImage ?? (familyHeroSlug ? `/games/art/${familyHeroSlug}_hero.jpg` : null);
62	  const heroIsGameArt = !ownHeroImage && !!heroImage;
63	  const longDescriptionHtml = mod.longDescription ? renderMarkdown(mod.longDescription.slice(0, 6000)) : null;
64	
65	  return (
66	    <PageShell eyebrow="NxLabs" title={mod.name} sub={mod.description ?? undefined} tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}>
67	      <p className="-mt-2 mb-4 text-xs text-tx-mute">
68	        <Link href="/dashboard/nxlabs" className="hover:underline">
69	          NxLabs
70	        </Link>{" "}
71	        /{" "}
72	        <Link href={`/dashboard/nxlabs/games/${mod.gameFamily}`} className="hover:underline">
73	          {mod.gameFamilyLabel}
74	        </Link>
75	      </p>
76	
77	      <div className="grid gap-8 lg:grid-cols-[1.4fr_1fr]">
78	        <div className="space-y-6">
79	          <div className="relative mb-2 min-h-[140px] overflow-hidden rounded-2xl border border-white/10">
80	            {heroImage && (
81	              <>
82	                {/* eslint-disable-next-line @next/next/no-img-element */}
83	                <img
84	                  src={heroImage}
85	                  alt=""
86	                  aria-hidden
87	                  className={`absolute inset-0 h-full w-full object-cover ${heroIsGameArt ? "opacity-40" : "opacity-30 blur-sm"}`}
88	                />
89	                <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/75 to-navy-950/30" />
90	              </>
91	            )}
92	            <div className="relative flex flex-wrap items-center gap-4 p-6">
93	              {mod.iconUrl ? (
94	                // eslint-disable-next-line @next/next/no-img-element
95	                <img src={mod.iconUrl} alt="" className="h-16 w-16 rounded-2xl border border-white/10 object-cover" />
96	              ) : (
97	                <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.06] text-2xl font-bold text-tx-mute">
98	                  {mod.name.slice(0, 1)}
99	                </div>
100	              )}
101	              {mod.authorName && <AuthorBadge name={mod.authorName} avatarUrl={mod.authorAvatarUrl} />}
102	            </div>
103	          </div>
104	
105	          {mod.galleryUrls.length > 0 && <GalleryStrip images={mod.galleryUrls} alt={mod.name} />}
106	
107	          {longDescriptionHtml && (
108	            <div className="card p-6">
109	              <h2 className="text-lg font-semibold text-white">Description</h2>
110	              {/* Same sanitizing renderer as the marketing detail page — see
111	                  its identical comment for why this is safe against
112	                  third-party markdown (lib/blog.ts's renderMarkdown escapes
113	                  text before any tag is produced). */}
114	              <div
115	                className="mt-3 text-sm text-tx-mute"
116	                // eslint-disable-next-line react/no-danger
117	                dangerouslySetInnerHTML={{ __html: longDescriptionHtml }}
118	              />
119	            </div>
120	          )}
121	
122	          <div className="card p-6">
123	            <h2 className="text-lg font-semibold text-white">Download</h2>
124	            {download ? (
125	              <>
126	                <a href={download.url} className="btn-primary mt-4 inline-flex" target="_blank" rel="noopener noreferrer nofollow">
127	                  {download.direct ? "Download file" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
128	                </a>
129	              </>
130	            ) : (
131	              <p className="mt-3 text-sm text-tx-mute">No download link is available for this entry right now.</p>
132	            )}
133	            <div className="mt-6">
134	              <AddToServerWidget modId={mod.id} gameFamily={mod.gameFamilyLabel} downloadUrl={download?.url ?? null} />
135	            </div>
136	            {!mod.upstreamOk && (
137	              <p className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
138	                {mod.upstreamNote || "This mod is no longer supported by its source."}
139	              </p>
140	            )}
141	          </div>
142	
143	          <RatingsAndComments
144	            modId={mod.id}
145	            avgRating={mod.avgRating}
146	            ratingCount={mod.ratingCount}
147	            initialComments={commentsPage.comments}
148	            initialCursor={commentsPage.nextCursor}
149	            myRating={myRating}
150	            isLoggedIn
151	            isAdmin={user.role === "ADMIN"}
152	            loginHref="/login"
153	          />
154	        </div>
155	
156	        <aside className="space-y-6">
157	          <div className="card p-6">
158	            <h2 className="text-sm font-semibold uppercase tracking-wide text-tx-mute">Details</h2>
159	            <dl className="mt-4 space-y-3 text-sm">
160	              <Row label="Game">{mod.gameFamilyLabel}</Row>
161	              <Row label="Category">{mod.category}</Row>
162	              <Row label="Source">{SOURCE_LABEL[mod.source] ?? mod.source}</Row>
163	              {mod.license && <Row label="License">{mod.license}</Row>}
164	              {downloads && <Row label="Downloads">{downloads}</Row>}
165	              {fileSize && <Row label="File size">{fileSize}</Row>}
166	              {mod.gameVersions.length > 0 && <Row label="Game versions">{mod.gameVersions.slice(-6).reverse().join(", ")}</Row>}
167	              {mod.loaders.length > 0 && <Row label="Loaders">{mod.loaders.join(", ")}</Row>}
168	              {mod.appliesToVariant && <Row label="Requires">{mod.appliesToVariant} server type</Row>}
169	              {mod.serverSide && <Row label="Server support">{mod.serverSide}</Row>}
170	              <Row label="Verified">{mod.verified ? `Yes — checked ${mod.verifiedAt?.toISOString().slice(0, 10)}` : "Not yet verified"}</Row>
171	            </dl>
172	          </div>
173	
174	          <div className="card p-6">
175	            <h2 className="text-sm font-semibold uppercase tracking-wide text-tx-mute">Recommended server</h2>
176	            {recommended ? (
177	              <p className="mt-3 text-sm text-tx-mute">
178	                Works well on <span className="text-white">{recommended.planName}</span> (
179	                {(recommended.ramMB / 1024).toFixed(recommended.ramMB % 1024 ? 1 : 0)} GB RAM) or higher —{" "}
180	                <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
181	                  deploy one
182	                </Link>
183	                .
184	              </p>
185	            ) : (
186	              <p className="mt-3 text-sm text-tx-mute">
187	                {mod.impactNote || "This is a light install and should run fine on any active plan for this game."}
188	              </p>
189	            )}
190	          </div>
191	        </aside>
192	      </div>
193	
194	      {related.length > 0 && (
195	        <div className="mt-12">
