1	/**
2	 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
3	 *
4	 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
5	 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
6	 * sites that must never disagree about what a mod "is":
7	 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
8	 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
9	 *   - app/sitemap.ts (which detail pages get indexed)
10	 *
11	 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
12	 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
13	 *
14	 * HONESTY: a mod only appears in the public/portal catalogue when
15	 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
16	 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
17	 * excluded rather than shown with a broken badge, matching how
18	 * lib/actions-mods.ts's getServerMods already filters for the per-server
19	 * panel. Fields the source never published (gameVersions, license, ...) stay
20	 * empty and the UI says so — never a guess.
21	 *
22	 * REAL PAGINATION (2026-09-19): every comment in this file used to say "small
23	 * catalogue (~124 rows), the whole set is returned in one shot, filters run
24	 * client-side" — true when this was hand-seeded, false the moment a real
25	 * bulk import (scripts/import-modrinth-catalog.ts) landed 32,000+ real
26	 * Modrinth rows in the `minecraft` family alone. A hard 400-row cap
27	 * (`CATALOG_LIST_CAP`, since removed) used to mean the other ~31,850 mods in
28	 * that family were permanently unreachable — no page 2 existed. `queryCatalogMods`
29	 * replaces `listCatalogMods`/`searchCatalogMods` with real server-side,
30	 * DB-level pagination (`skip`/`take` + a real `count()`), and search/sort/
31	 * category-filter all run as part of the SAME query rather than over an
32	 * in-memory array — see StoreBrowser.tsx's own header comment for why search
33	 * specifically had to move server-side (its placeholder text promises to
34	 * search the whole catalogue, not just whatever page happens to be loaded).
35	 */
36	import { db } from "./db";
