112	/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
113	async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
114	  if (modIds.length === 0) return new Map();
115	  const rows = await db.modRating.groupBy({
116	    by: ["gameModId"],
117	    where: { gameModId: { in: modIds } },
118	    _avg: { rating: true },
119	    _count: { rating: true },
120	  });
121	  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
122	}
