185	export type CatalogSort = "featured" | "downloads" | "latest" | "rating";
186	
187	export type CatalogPage = {
188	  mods: ModSummary[];
189	  total: number;
190	  page: number;
191	  totalPages: number;
192	  perPage: number;
193	};
194	
195	/**
196	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
197	 * the one honest exception: avgRating is computed from a separate ModRating
198	 * table with no cached column on GameMod, and Prisma's relation-aggregate
199	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
200	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
201	 * and re-sorting by rating WITHIN each page (below) is a documented
202	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
203	 * re-ordered by rating, not the true 25th-48th highest-rated mods
204	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
205	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
206	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
207	 * the rating mutation) and give this its own real orderBy.
208	 */
209	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
210	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
211	  downloads: [{ downloads: "desc" }, { name: "asc" }],
212	  latest: [{ createdAt: "desc" }],
213	  rating: [{ downloads: "desc" }, { name: "asc" }],
214	};
215	
216	/**
217	 * Real, server-side, paginated + searched + sorted catalogue query — the
218	 * single data source behind every StoreBrowser instance (marketing and
219	 * portal, cross-game and per-family). Replaces the old
220	 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
221	 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
222	 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
223	 * capping the catalogue at families with thousands+ of real imported rows.
224	 */
225	export async function queryCatalogMods(opts: {
226	  family?: string;
227	  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
228	  category?: string;
229	  q?: string;
230	  sort?: CatalogSort;
231	  page?: number;
232	  perPage?: number;
233	}): Promise<CatalogPage> {
234	  const sort = opts.sort ?? "featured";
235	  const q = (opts.q ?? "").trim();
236	  const where: Prisma.GameModWhereInput = {
237	    active: true,
238	    upstreamOk: true,
239	    ...(opts.family ? { gameFamily: opts.family } : {}),
240	    ...(opts.category ? { category: opts.category } : {}),
241	    ...(q
242	      ? {
243	          OR: [
244	            { name: { contains: q, mode: "insensitive" } },
245	            { category: { contains: q, mode: "insensitive" } },
246	            { description: { contains: q, mode: "insensitive" } },
247	          ],
248	        }
249	      : {}),
250	  };
251	
252	  const total = await db.gameMod.count({ where });
253	  const { skip, take, page, pages, perPage } = paginate(
254	    { page: opts.page != null ? String(opts.page) : undefined },
255	    total,
256	    opts.perPage ?? CATALOG_PAGE_SIZE
257	  );
258	
259	  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
260	  const aggs = await ratingAggs(rows.map((r) => r.id));
261	  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
262	  if (sort === "rating") {
263	    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
264	  }
265	
266	  return { mods, total, page, totalPages: pages, perPage };
267	}
