270	 * Curated "Featured mods" rail — real `GameMod.featured` rows only (an
271	 * admin/import-time editorial flag, same field `ORDER_BY.featured` already
272	 * sorts by first), never a synthetic pick. Ordered by real downloads within
273	 * the featured set so the best-known featured mod leads. Returns fewer than
274	 * `take` (down to zero) when a family simply hasn't had any mods marked
275	 * featured yet — callers render nothing rather than pad with non-featured
276	 * rows, matching this file's no-guessing rule.
277	 */
278	export async function listFeaturedMods(family: string, take = 8): Promise<ModSummary[]> {
279	  const rows = await db.gameMod.findMany({
