281	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
282	    take,
283	  });
284	  const aggs = await ratingAggs(rows.map((r) => r.id));
285	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
