400	export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;
401	
402	/**
403	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
404	 * light-impact mods run on any active plan for the family; moderate needs at
405	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
406	 * for the family that clears the bar, or null if none does (never guesses a
407	 * number that isn't a real, active, orderable plan).
408	 */
409	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
410	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
411	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
412	  const pick = candidates[0];
413	  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
414	}
415	
416	export function formatDownloads(n: number | null): string | null {
417	  if (n == null) return null;
418	  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(n >= 10_000_000_000 ? 0 : 1)}B`;
419	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
420	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
421	  return String(n);
422	}
423	
424	export function formatBytes(bytes: number | null): string | null {
425	  if (!bytes || bytes <= 0) return null;
426	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
427	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
428	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
429	}
