431	/**
432	 * The real, authoritative download for a mod detail page. Prefers the
433	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
434	 * install it) so a visitor gets the actual file, not just a landing page;
435	 * falls back to the mod's own project/resource page (still the real,
436	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
437	 * be resolved live or isn't one of the three we know how to resolve.
438	 */
439	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
440	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
441	  const id = mod.sourceId ?? "";
442	  if (!id) return fallback;
443	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
444	  try {
445	    if (mod.source === "modrinth") {
446	      const headers: Record<string, string> = { "User-Agent": UA };
447	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
448	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
449	      if (!res.ok) return fallback;
450	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
451	      const v = versions[0];
452	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
453	      return file ? { url: file.url, direct: true } : fallback;
454	    }
455	    if (mod.source === "spigotmc") {
456	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
457	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
458	    }
459	    if (mod.source === "thunderstore") {
460	      const [namespace, ...rest] = id.split("-");
461	      if (!namespace || !rest.length) return fallback;
462	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
463	        headers: { "User-Agent": UA },
464	        next: { revalidate: 3600 },
465	      });
466	      if (!res.ok) return fallback;
