export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;

/**
 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
 * light-impact mods run on any active plan for the family; moderate needs at
 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
 * for the family that clears the bar, or null if none does (never guesses a
 * number that isn't a real, active, orderable plan).
 */
export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
  const pick = candidates[0];
  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
}

